from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def read(rel):
    return (ROOT / rel).read_text(encoding="utf-8")


def write(rel, content):
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")


def replace_once(text, old, new, label):
    if new in text:
        return text
    if old not in text:
        raise RuntimeError(f"Missing patch target: {label}")
    return text.replace(old, new, 1)

# -----------------------------------------------------------------------------
# 1) Pin the provider matching the selected layout.
# -----------------------------------------------------------------------------
rel = "mobile/modules/hassoun-widget/android/src/main/java/ca/wopt/hassounwidget/HassounWidgetModule.kt"
s = read(rel)
old = '''      // The provider metadata already uses the shallow slim initialLayout,\n      // which is the Samsung-safe shell. Do not overwrite the user's saved layout.\n      // Ask Android to send us a success broadcast after the widget is actually\n      // placed, then populate it immediately so it never remains an empty shell.\n      val refreshIntent = android.content.Intent(context, HassounPrayerWidgetProvider::class.java).apply {\n        action = HassounWidgetStore.ACTION_REFRESH\n      }\n      val successCallback = android.app.PendingIntent.getBroadcast(\n        context,\n        7610,\n        refreshIntent,\n        android.app.PendingIntent.FLAG_UPDATE_CURRENT or android.app.PendingIntent.FLAG_IMMUTABLE\n      )\n      manager.requestPinAppWidget(ComponentName(context, HassounPrayerWidgetProvider::class.java), null, successCallback)\n'''
new = '''      val prefs = context.getSharedPreferences(HassounWidgetStore.PREFS, Context.MODE_PRIVATE)\n      val selectedLayout = prefs.getString("layout", "full") ?: "full"\n      val providerClass = when (selectedLayout) {\n        "square" -> HassounSquareWidgetProvider::class.java\n        "vertical" -> HassounVerticalWidgetProvider::class.java\n        "slim", "compact", "next" -> HassounSlimWidgetProvider::class.java\n        else -> HassounPrayerWidgetProvider::class.java\n      }\n      val requestCode = when (selectedLayout) {\n        "square" -> 7612\n        "vertical" -> 7614\n        "slim", "compact", "next" -> 7611\n        else -> 7620\n      }\n      val refreshIntent = android.content.Intent(context, HassounPrayerWidgetProvider::class.java).apply {\n        action = HassounWidgetStore.ACTION_REFRESH\n      }\n      val successCallback = android.app.PendingIntent.getBroadcast(\n        context,\n        requestCode,\n        refreshIntent,\n        android.app.PendingIntent.FLAG_UPDATE_CURRENT or android.app.PendingIntent.FLAG_IMMUTABLE\n      )\n      manager.requestPinAppWidget(ComponentName(context, providerClass), null, successCallback)\n'''
s = replace_once(s, old, new, "selected provider pin")
write(rel, s)

# -----------------------------------------------------------------------------
# 2) Native renderer: provider always owns its real layout; cap fonts per size;
#    only Large + Vertical show the full five-prayer strip.
# -----------------------------------------------------------------------------
rel = "mobile/modules/hassoun-widget/android/src/main/java/ca/wopt/hassounwidget/HassounPrayerWidgetProvider.kt"
s = read(rel)
old = '''      val layout = if (isLockScreen) requestedLayout else when {\n        // Samsung can invoke onUpdate before it gives the widget usable dimensions.\n        // Always use the shallow safe shell for that very first render, including\n        // the Large 4x2 provider. This prevents the launcher "Couldn't add widget" failure.\n        minWidth <= 0 || minHeight <= 0 -> "slim"\n        providerLayout != null -> providerLayout\n        minHeight >= minWidth * 1.35 -> "vertical"\n        minWidth <= 220 && minHeight >= 150 -> "square"\n        minHeight <= 80 || minWidth >= minHeight * 3.20 -> "slim"\n        requestedLayout == "square" -> "square"\n        requestedLayout == "slim" || requestedLayout == "compact" || requestedLayout == "next" -> "slim"\n        else -> "full"\n      }\n'''
new = '''      val layout = if (isLockScreen) requestedLayout else providerLayout ?: when {\n        minHeight >= minWidth * 1.35 -> "vertical"\n        minWidth <= 220 && minHeight >= 150 -> "square"\n        minHeight <= 80 || minWidth >= minHeight * 3.20 -> "slim"\n        requestedLayout == "square" -> "square"\n        requestedLayout == "slim" || requestedLayout == "compact" || requestedLayout == "next" -> "slim"\n        else -> "full"\n      }\n'''
s = replace_once(s, old, new, "provider owned layout")

old = '''        val timeSp = when (layout) {\n          "vertical" -> when (timeSize) { "small" -> 21f; "medium" -> 25f; "xlarge" -> 34f; else -> 29f }\n          "square" -> when (timeSize) { "small" -> 20f; "medium" -> 24f; "xlarge" -> 32f; else -> 28f }\n          "slim", "compact", "next" -> when (timeSize) { "small" -> 24f; "medium" -> 29f; "xlarge" -> 40f; else -> 34f }\n          else -> when (timeSize) { "small" -> 25f; "medium" -> 31f; "xlarge" -> 44f; else -> 37f }\n        }\n        val prayerNameSp = when (layout) {\n          "vertical" -> when (focus) { "all" -> 21f; "balanced" -> 25f; else -> 30f }\n          "square" -> when (focus) { "all" -> 20f; "balanced" -> 24f; else -> 29f }\n          "slim", "compact", "next" -> when (focus) { "all" -> 20f; "balanced" -> 25f; else -> 31f }\n          else -> when (focus) { "all" -> 22f; "balanced" -> 27f; else -> 34f }\n        }\n'''
new = '''        val timeSp = when (layout) {\n          "vertical" -> when (timeSize) { "small" -> 21f; "medium" -> 24f; "xlarge" -> 32f; else -> 28f }\n          "square" -> when (timeSize) { "small" -> 18f; "medium" -> 21f; "xlarge" -> 28f; else -> 24f }\n          "slim", "compact", "next" -> when (timeSize) { "small" -> 18f; "medium" -> 22f; "xlarge" -> 30f; else -> 26f }\n          else -> when (timeSize) { "small" -> 20f; "medium" -> 24f; "xlarge" -> 32f; else -> 28f }\n        }\n        val prayerNameSp = when (layout) {\n          "vertical" -> when (focus) { "all" -> 20f; "balanced" -> 24f; else -> 28f }\n          "square" -> when (focus) { "all" -> 19f; "balanced" -> 22f; else -> 26f }\n          "slim", "compact", "next" -> when (focus) { "all" -> 18f; "balanced" -> 21f; else -> 24f }\n          else -> when (focus) { "all" -> 20f; "balanced" -> 24f; else -> 28f }\n        }\n'''
s = replace_once(s, old, new, "responsive hero font caps")

old = '''          val countdownSp = if (countdownStyle != "circle") 10f else when {\n            isLockScreen -> 17f\n            layout == "slim" || layout == "compact" -> 10.5f\n            layout == "square" -> 14f\n            layout == "vertical" -> 16f\n            else -> 17f\n          }\n'''
new = '''          val countdownSp = if (countdownStyle != "circle") 10f else when {\n            isLockScreen -> 15f\n            layout == "slim" || layout == "compact" -> 10f\n            layout == "square" -> 11.5f\n            layout == "vertical" -> 13f\n            else -> 11.5f\n          }\n'''
s = replace_once(s, old, new, "countdown font caps")

s = replace_once(
    s,
    '        val supportsPrayerStrip = isLockScreen || layout in setOf("full", "vertical", "square", "slim", "next", "compact")\n',
    '        val supportsPrayerStrip = isLockScreen || layout in setOf("full", "vertical")\n',
    "prayer strip visibility by layout",
)
s = replace_once(
    s,
    '          bindPrayerStrip(views, next.day, locale, next.key, isLockScreen, theme, showArabicNames, highlightNext, timeSize, focus)\n',
    '          bindPrayerStrip(views, next.day, locale, next.key, isLockScreen, theme, showArabicNames, highlightNext, timeSize, focus, layout)\n',
    "pass layout to prayer strip",
)
s = replace_once(
    s,
    '    private fun bindPrayerStrip(views: RemoteViews, day: JSONObject, locale: String, nextKey: String, lockScreen: Boolean, theme: String, showArabic: Boolean, highlightNext: Boolean, timeSize: String, focus: String) {\n',
    '    private fun bindPrayerStrip(views: RemoteViews, day: JSONObject, locale: String, nextKey: String, lockScreen: Boolean, theme: String, showArabic: Boolean, highlightNext: Boolean, timeSize: String, focus: String, layout: String) {\n',
    "prayer strip signature",
)
old = '''        views.setTextColor(id, if (highlightNext && key == nextKey) accent else baseText)\n        val stripSp = if (lockScreen) 10f else when (timeSize) {\n          "small" -> 9.5f\n          "medium" -> 11f\n          "xlarge" -> 14f\n          else -> 12.5f\n        }\n        views.setTextViewTextSize(id, TypedValue.COMPLEX_UNIT_SP, stripSp)\n'''
new = '''        views.setTextColor(id, if (highlightNext && key == nextKey) accent else baseText)\n        val chipBackground = if (theme == "ivory") R.drawable.hassoun_widget_prayer_chip_light else R.drawable.hassoun_widget_prayer_chip_dark\n        views.setInt(id, "setBackgroundResource", chipBackground)\n        val stripSp = if (lockScreen) 9.5f else when (layout) {\n          "vertical" -> when (timeSize) { "small" -> 8.5f; "medium" -> 9.5f; "xlarge" -> 11.5f; else -> 10.5f }\n          else -> when (timeSize) { "small" -> 7.5f; "medium" -> 8.5f; "xlarge" -> 10.5f; else -> 9.5f }\n        }\n        views.setTextViewTextSize(id, TypedValue.COMPLEX_UNIT_SP, stripSp)\n'''
s = replace_once(s, old, new, "prayer strip native styling")
write(rel, s)

# -----------------------------------------------------------------------------
# 3) Premium light/dark chip surfaces.
# -----------------------------------------------------------------------------
write("mobile/modules/hassoun-widget/android/src/main/res/drawable/hassoun_widget_prayer_chip_light.xml", '''<?xml version="1.0" encoding="utf-8"?>\n<shape xmlns:android="http://schemas.android.com/apk/res/android" android:shape="rectangle">\n  <solid android:color="#80FFFFFF"/>\n  <stroke android:width="1dp" android:color="#5CB89B6A"/>\n  <corners android:radius="12dp"/>\n</shape>\n''')
write("mobile/modules/hassoun-widget/android/src/main/res/drawable/hassoun_widget_prayer_chip_dark.xml", '''<?xml version="1.0" encoding="utf-8"?>\n<shape xmlns:android="http://schemas.android.com/apk/res/android" android:shape="rectangle">\n  <solid android:color="#18FFFFFF"/>\n  <stroke android:width="1dp" android:color="#32FFFFFF"/>\n  <corners android:radius="12dp"/>\n</shape>\n''')

